'use client';

import { useEffect, useState } from 'react';
import { AlertTriangle, GitCompare, ShieldAlert } from 'lucide-react';
import { apiClient, type ApiChange, type ApiImpactFinding } from '@/lib/api-client';

export function ChangeIntelligence({ projectId }: { projectId: string }) {
  const [changes, setChanges] = useState<ApiChange[]>([]);
  const [findings, setFindings] = useState<ApiImpactFinding[]>([]);
  const [summary, setSummary] = useState({ totalChanges: 0, breakingChanges: 0, potentiallyBreaking: 0, openFindings: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  useEffect(() => { void apiClient.analytics.impact(projectId).then((result) => { if (result.success && result.data) { setChanges(result.data.changes); setFindings(result.data.findings); setSummary(result.data.summary); } else setError(result.error?.message || 'Could not load change intelligence.'); setLoading(false); }); }, [projectId]);
  if (loading) return <div className="data-state">Loading change intelligence...</div>;
  if (error) return <div className="data-alert">{error}</div>;
  return <div className="workspace-page"><div className="timeline-heading"><div><p className="page-kicker">Analysis</p><h2>Change intelligence</h2><p>Persisted contract comparisons and dependency evidence for this project.</p></div><GitCompare size={20} /></div><div className="analytics-metrics"><article><GitCompare size={17}/><span>Total changes</span><b>{summary.totalChanges}</b></article><article><AlertTriangle size={17}/><span>Breaking</span><b>{summary.breakingChanges}</b></article><article><ShieldAlert size={17}/><span>Potentially breaking</span><b>{summary.potentiallyBreaking}</b></article><article><AlertTriangle size={17}/><span>Open findings</span><b>{summary.openFindings}</b></article></div><section className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Detected changes</p><h3>Reviewable contract differences</h3></div><span>{changes.length} records</span></div>{changes.length ? <div className="activity-list">{changes.map((change) => <article key={change.id}><span className="timeline-dot"/><div><b>{change.changeType.replaceAll('_', ' ')}</b><time>{change.classification} - {change.severity}</time><small>{change.contractPath} - {change.explanation}</small></div></article>)}</div> : <div className="empty-state"><b>No comparisons have been run</b><p>Compare two persisted versions to detect contract changes.</p></div>}</section><section className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Breaking dependencies</p><h3>Evidence-aware impact findings</h3></div><span>{findings.length} findings</span></div>{findings.length ? <div className="activity-list">{findings.map((finding) => <article key={finding.id}><span className="timeline-dot"/><div><b>{finding.impact} impact - {finding.severity}</b><time>{finding.confidence} - {finding.status}</time><small>{finding.evidence}</small></div></article>)}</div> : <div className="empty-state"><b>No impact findings</b><p>Run analysis on a detected change to evaluate dependent APIs.</p></div>}</section></div>;
}
